INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Menyalin Ulang Berulang Kali$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Bekerja dengan banyak data — misalnya memindahkan alamat, nomor telepon, atau potongan teks dari web ke dokumen — sering terasa melelahkan karena clipboard biasa hanya menyimpan satu item terakhir. Setiap kali menyalin yang baru, yang lama hilang dan harus disalin ulang.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Apa Itu Clipboard History$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Clipboard History adalah fitur bawaan Windows 10 dan Windows 11 yang menyimpan hingga 25 item terakhir yang disalin (teks dan gambar). Semua tersimpan sementara dan bisa dipilih ulang kapan saja tanpa menyalin ulang dari sumbernya. Fitur ini mati secara default sehingga banyak pengguna tidak tahu ia ada.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Langkah Mengaktifkan dan Memakai$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Siapkan komputer Windows 10 (versi 1809 ke atas) atau Windows 11 — fitur ini bawaan, tanpa aplikasi tambahan.$txt$, $txt$Tekan tombol Windows + V pada keyboard. Jendela kecil akan muncul dan meminta izin mengaktifkan riwayat clipboard — klik Turn on.$txt$, $txt$Mulai sekarang, setiap teks atau gambar yang disalin (Ctrl+C) otomatis tersimpan dalam riwayat.$txt$, $txt$Untuk menempel dari riwayat, tekan Windows + V, lalu klik item yang diinginkan dari daftar.$txt$, $txt$Item yang sering dipakai bisa disematkan: klik ikon pin pada item agar tidak terhapus saat riwayat dibersihkan.$txt$, $txt$Untuk menghapus satu item, klik ikon titik tiga pada item lalu pilih Delete; untuk menghapus semua, pilih Clear all.$txt$, $txt$Aktifkan sinkronisasi (opsional): buka Settings > System > Clipboard, nyalakan Sync across devices agar riwayat terbawa ke perangkat Windows lain yang memakai akun Microsoft yang sama.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Risiko dan Batasan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Riwayat clipboard terhapus saat komputer dimatikan atau di-restart, kecuali item yang disematkan (pin).$txt$, $txt$Jangan menyalin kata sandi atau data sensitif lalu membiarkannya tersimpan di riwayat pada komputer bersama.$txt$, $txt$Sinkronisasi antar perangkat mengirim data clipboard ke server Microsoft — matikan bila menangani data rahasia.$txt$, $txt$Gambar berukuran besar memakan ruang riwayat; item tertua otomatis terbuang saat melebihi 25 item.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Pemeriksaan Hasil$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Salin tiga teks berbeda dari tiga tempat, lalu tekan Windows + V — ketiganya harus muncul dalam daftar dan bisa ditempel satu per satu. Bila hanya item terakhir yang muncul, berarti fitur belum aktif; ulangi langkah pertama.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Biasakan memakai Win+V setiap bekerja dengan banyak potongan teks$txt$, $txt$Sematkan (pin) template teks yang dipakai setiap hari, misalnya format email atau alamat kantor$txt$, $txt$Matikan sinkronisasi bila memakai komputer kantor dengan data sensitif$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Panik Saat Suhu Naik$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Demam tinggi membuat banyak orang panik, apalagi pada anak. Padahal demam adalah reaksi alami tubuh melawan infeksi. Yang penting bukan sekadar menurunkan angka di termometer, melainkan mengenali kapan demam berbahaya dan kapan cukup ditangani di rumah.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Apa Itu Demam Tinggi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Suhu tubuh normal berkisar 36,5–37,5 derajat Celsius. Demam umumnya disebut tinggi bila mencapai 39 derajat Celsius atau lebih. Pada bayi di bawah 3 bulan, suhu 38 derajat Celsius atau lebih sudah tergolong darurat dan wajib segera diperiksa dokter, berapa pun angkanya.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Langkah Pertolongan Pertama di Rumah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Siapkan termometer digital, air minum yang cukup, obat penurun panas (paracetamol/ibuprofen sesuai dosis kemasan), kain lap, dan nomor fasilitas kesehatan terdekat.$txt$, $txt$Ukur suhu dengan termometer dan catat angkanya beserta waktunya.$txt$, $txt$Berikan banyak cairan: air putih, sup hangat, atau oralit bila berkeringat banyak.$txt$, $txt$Kompres dengan air hangat (bukan air es) di dahi, ketiak, dan lipatan paha.$txt$, $txt$Pakaikan pakaian tipis dan jaga suhu ruangan sejuk; jangan menyelimuti tebal-tebal.$txt$, $txt$Bila suhu di atas 38,5 derajat dan penderita tidak nyaman, berikan penurun panas sesuai dosis pada kemasan, lalu pantau ulang suhu setiap 2–4 jam.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Risiko dan Kesalahan Umum$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Jangan mengompres dengan alkohol atau air es — bisa membuat pembuluh darah menyempit dan suhu justru sulit turun.$txt$, $txt$Jangan memberi aspirin pada anak karena berisiko sindrom Reye yang berbahaya.$txt$, $txt$Jangan memaksa makan bila tidak nafsu; cairan jauh lebih penting daripada makanan saat demam.$txt$, $txt$Hindari membungkus penderita dengan selimut tebal karena panas tubuh terperangkap.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Tanda Bahaya: Segera ke Dokter atau IGD$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Bayi di bawah 3 bulan dengan suhu 38 derajat Celsius atau lebih.$txt$, $txt$Demam di atas 40 derajat Celsius yang tidak turun dengan obat.$txt$, $txt$Kejang, leher kaku, ruam yang tidak hilang saat ditekan, atau kesadaran menurun.$txt$, $txt$Muntah terus-menerus, sulit bernapas, atau tidak buang air kecil lebih dari 8 jam.$txt$, $txt$Demam lebih dari 3 hari tanpa perbaikan.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Evaluasi, Pencegahan, dan Catatan Penting$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Catatan suhu harian membantu dokter menegakkan diagnosis bila akhirnya perlu berobat. Untuk pencegahan, biasakan cuci tangan, cukup istirahat, dan lengkapi imunisasi sesuai jadwal. Artikel ini berisi informasi umum dan bukan pengganti nasihat medis — bila ragu atau gejala memburuk, segera konsultasikan ke dokter atau fasilitas kesehatan terdekat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Siapa Orang Sunda$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Suku Sunda adalah kelompok etnis terbesar kedua di Indonesia setelah Jawa, mendiami sebagian besar wilayah Jawa Barat dan Banten. Bahasa Sunda dipakai sehari-hari oleh puluhan juta penutur dan memiliki tingkatan tutur (undak-usuk: kasar, loma, lemes) yang mencerminkan penghormatan kepada lawan bicara — kesopanan berbahasa dianggap cerminan budi pekerti seseorang.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Silih Asah, Silih Asih, Silih Asuh$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Tiga falsafah ini adalah jantung budaya Sunda. Silih asah (saling mengasah pikiran dan pengetahuan): kritik yang membangun dianggap bentuk kasih sayang, diwujudkan dalam musyawarah dan nasihat orang tua. Silih asih (saling mengasihi): tercermin dalam gotong royong membangun rumah, membantu tetangga kesusahan, dan berbagi makanan saat hajatan. Silih asuh (saling membimbing): yang tua membimbing yang muda, yang muda menghormati yang tua — dasar kuatnya ikatan keluarga Sunda.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Kearifan Alam dan Budaya$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Masyarakat Sunda tradisional memegang prinsip menjaga keseimbangan dengan alam: sistem pertanian selaras musim, aturan adat tentang hutan (leuweung larangan), dan upacara Seren Taun sebagai syukur atas panen. Seni Sunda — angklung, gamelan degung, wayang golek, tari jaipong — menjadi media pewarisan nilai-nilai ini lintas generasi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Relevansi di Zaman Modern$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Tiga nilai silih asah, silih asih, silih asuh tetap relevan: di tempat kerja sebagai dasar kerja sama tim, di media sosial sebagai pengingat berdiskusi santun, dan di keluarga sebagai penguat ikatan antar generasi. Falsafah ini bukan pajangan museum, melainkan panduan praktis hidup bermasyarakat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Ringkasan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Suku Sunda: etnis terbesar kedua di Indonesia, berpusat di Jawa Barat dan Banten$txt$, $txt$Silih asah: saling mengasah ilmu dan mengingatkan$txt$, $txt$Silih asih: saling mengasihi dan gotong royong$txt$, $txt$Silih asuh: saling membimbing lintas generasi$txt$, $txt$Warisan budaya: angklung, wayang golek, Seren Taun, undak-usuk basa — lestarikan dengan memakai bahasa Sunda di rumah dan mengenalkan seni tradisional kepada anak$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Unsur yang Cair di Suhu Ruang$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Bromin (simbol Br, nomor atom 35) adalah satu dari hanya dua unsur yang berwujud cair pada suhu ruang — yang satunya adalah raksa (merkuri). Ia berupa cairan berwarna merah kecokelatan yang mudah menguap menjadi gas berwarna jingga dengan bau menyengat; namanya berasal dari bahasa Yunani bromos yang berarti bau busuk. Ia ditemukan pada tahun 1826 oleh Antoine Jérôme Balard dari Prancis yang mengisolasinya dari air laut.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Sifat dan Posisi di Tabel Periodik$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Bromin termasuk golongan halogen (golongan 17, periode 4), segolongan dengan fluor, klor, dan iodin. Ia sangat reaktif, bersifat oksidator kuat, dan uapnya korosif serta beracun — berada di tengah: lebih reaktif daripada iodin namun kurang reaktif daripada klor. Titik leburnya minus 7,2 derajat Celsius dan titik didihnya 58,8 derajat Celsius, sangat rendah untuk ukuran cairan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Bromin di Alam dan Kegunaannya$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Bromin tidak ditemukan bebas di alam karena kereaktifannya; ia selalu terikat sebagai senyawa bromida, terutama di air laut dan danau garam (Laut Mati adalah penghasil utama). Senyawa bromin dipakai sebagai penghambat api pada elektronik dan furnitur, bahan obat-obatan, bahan fotografi analog (perak bromida), pemurnian air, dan pengolahan emas. Senyawa bromin juga dipakai sebagai disinfektan kolam renang, sementara klor lebih umum untuk air minum.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Mengapa Berbahaya$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Uap bromin mengiritasi mata, hidung, dan saluran pernapasan; paparan tinggi bisa menyebabkan luka bakar kimia pada kulit dan kerusakan paru-paru. Karena itu bromin hanya boleh ditangani tenaga terlatih dengan alat pelindung di laboratorium berventilasi baik — bukan bahan untuk percobaan rumahan. Bila menemukan wadah berlabel bromin, jangan dibuka; jauhkan dari jangkauan anak dan hubungi pihak berwenang.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Ringkasan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Bromin (Br, 35): cairan merah kecokelatan, satu dari dua unsur cair di suhu ruang$txt$, $txt$Golongan halogen: sangat reaktif, uapnya beracun dan korosif$txt$, $txt$Sumber: air laut dan danau garam; ditemukan 1826 oleh Balard$txt$, $txt$Kegunaan: penghambat api, obat, fotografi analog, pengolahan air, disinfektan kolam$txt$, $txt$Hanya ditangani tenaga terlatih dengan alat pelindung$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Menjelaskan pengertian SPLDV$txt$, $txt$Menyelesaikan SPLDV dengan metode substitusi, eliminasi, dan campuran$txt$, $txt$Menyelesaikan soal cerita yang berkaitan dengan SPLDV$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian SPLDV$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Sistem Persamaan Linear Dua Variabel (SPLDV) adalah dua persamaan linear yang memiliki dua variabel yang sama dan saling berkaitan. Bentuk umumnya: a1x + b1y = c1 dan a2x + b2y = c2. Penyelesaiannya adalah pasangan nilai (x, y) yang memenuhi kedua persamaan sekaligus — selalu periksa jawaban dengan memasukkannya ke kedua persamaan awal.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Tiga Metode Penyelesaian$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Substitusi artinya mengganti: nyatakan satu variabel dari satu persamaan, lalu masukkan ke persamaan lainnya (contoh: dari x + y = 10 diperoleh x = 10 − y; substitusi ke 2x − y = 5 menghasilkan y = 5, x = 5). Eliminasi artinya menghilangkan satu variabel dengan menjumlahkan atau mengurangkan kedua persamaan setelah koefisiennya disamakan (contoh: x + y = 10 dan 2x − y = 5 dijumlahkan langsung menjadi 3x = 15). Metode campuran menggabungkan keduanya: eliminasi dulu satu variabel, lalu substitusikan nilainya untuk mencari variabel lainnya — cara paling fleksibel untuk soal yang koefisiennya tidak berpasangan rapi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Contoh Soal Terpecahkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Harga 3 buku dan 2 pensil Rp17.000, sedangkan 2 buku dan 3 pensil Rp13.000. Misal buku = x, pensil = y: 3x + 2y = 17000 dan 2x + 3y = 13000. Kalikan persamaan pertama dengan 3 dan kedua dengan 2: 9x + 6y = 51000 dan 4x + 6y = 26000. Kurangkan: 5x = 25000, x = 5000. Substitusi: 3(5000) + 2y = 17000, 2y = 2000, y = 1000. Jadi harga buku Rp5.000 dan pensil Rp1.000. Untuk soal cerita, selalu tulis pemisalan variabelnya terlebih dahulu.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Soal Latihan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Selesaikan SPLDV: 2x + y = 11 dan x − y = 1 dengan metode substitusi.$txt$, $txt$Selesaikan SPLDV: 3x + 2y = 16 dan x − 2y = 0 dengan metode eliminasi.$txt$, $txt$Harga 4 kg apel dan 3 kg jeruk Rp92.000; harga 2 kg apel dan 5 kg jeruk Rp90.000. Tentukan harga 1 kg apel dan 1 kg jeruk.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Dari x − y = 1 diperoleh x = y + 1; substitusi: 2(y+1) + y = 11 → 3y = 9 → y = 3, x = 4. Himpunan penyelesaian: {(4, 3)}.$txt$, $txt$Jumlahkan kedua persamaan: 4x = 16 → x = 4; substitusi: 4 − 2y = 0 → y = 2. Himpunan penyelesaian: {(4, 2)}.$txt$, $txt$Misal apel = x, jeruk = y: 4x + 3y = 92000 dan 2x + 5y = 90000. Kalikan persamaan kedua dengan 2: 4x + 10y = 180000; kurangkan dengan persamaan pertama: 7y = 88000 → y ≈ 12.571. (Soal ini menghasilkan desimal; pada praktiknya pilih angka yang menghasilkan bilangan bulat.)$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Mengenal jenis-jenis uang rupiah$txt$, $txt$Menyebutkan nilai pecahan uang kertas dan logam$txt$, $txt$Menggunakan uang dengan bijak dalam kegiatan jual beli sederhana$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Uang$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Uang adalah alat tukar yang sah untuk membeli barang dan jasa. Di Indonesia, uang resmi disebut rupiah, disingkat Rp. Tanpa uang, orang zaman dulu bertukar barang secara langsung (barter) — misalnya menukar beras dengan ikan — yang merepotkan karena sulit menentukan nilai tukarnya.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Uang Kertas dan Uang Logam Rupiah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Uang kertas rupiah memiliki pecahan Rp1.000, Rp2.000, Rp5.000, Rp10.000, Rp20.000, Rp50.000, dan Rp100.000 — setiap pecahan memiliki warna dan gambar pahlawan yang berbeda agar mudah dikenali, dan dipakai untuk nilai yang lebih besar. Uang logam terdiri atas pecahan Rp100, Rp200, Rp500, dan Rp1.000; terbuat dari bahan logam sehingga awet dan cocok untuk nilai kecil, misalnya membeli permen. Lima lembar Rp2.000 sama nilainya dengan satu lembar Rp10.000, dan dua keping Rp500 sama dengan satu lembar Rp1.000 — memahami kesetaraan ini membantu menghitung kembalian saat berbelanja.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Contoh Jual Beli$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Siti membeli pensil seharga Rp3.000 dan membayar dengan selembar Rp5.000. Kembaliannya adalah Rp5.000 − Rp3.000 = Rp2.000 — penjual bisa memberi satu lembar Rp2.000 atau dua keping Rp1.000.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Menggunakan Uang dengan Bijak$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Bedakan kebutuhan (makanan, alat sekolah) dan keinginan (mainan, jajan berlebih).$txt$, $txt$Biasakan menabung sebagian uang saku, misalnya di celengan.$txt$, $txt$Jangan membeli barang hanya karena ikut-ikutan teman.$txt$, $txt$Rawat uang: jangan melipat, mencoret, atau meremas uang kertas.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Soal Latihan dan Kunci Jawaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Sebutkan tiga pecahan uang kertas rupiah! (Contoh: Rp1.000, Rp5.000, Rp10.000)$txt$, $txt$Budi punya dua keping Rp500 dan satu lembar Rp2.000. Berapa jumlah uang Budi? (Rp3.000)$txt$, $txt$Ibu memberi Rp10.000 untuk membeli buku Rp7.500. Berapa kembaliannya? (Rp2.500)$txt$])));
